import { describe, expect, it } from "vitest"
import { buildPreviewModel, type PreviewModel } from "./model"

const saved: PreviewModel = {
    profile: { name: "Aditya Patil", image: "/files/a.png" },
    workspace: { name: "Acme", logo: "/files/acme.png" },
    channel: { name: "general" },
    people: [{ id: "user-priya", name: "Priya" }],
    leave: false,
}

describe("buildPreviewModel", () => {
    it("shows saved data when there's no draft", () => {
        expect(buildPreviewModel(saved, {})).toEqual(saved)
    })

    it("lets the open step's draft override what's saved", () => {
        const model = buildPreviewModel(saved, { workspace: { name: "Acme Labs" } })
        expect(model.workspace).toEqual({ name: "Acme Labs", logo: "/files/acme.png" })
        expect(model.profile).toEqual(saved.profile)
    })

    it("falls back to saved data when a draft field is empty", () => {
        const model = buildPreviewModel(saved, { profile: { name: "   " }, workspace: { name: "" } })
        expect(model.profile?.name).toBe("Aditya Patil")
        expect(model.workspace?.name).toBe("Acme")
    })

    it("takes the channel type the open step has picked", () => {
        const model = buildPreviewModel({ ...saved, channel: { name: "general", type: "Public" } }, { channel: { name: "general", type: "Private" } })
        expect(model.channel).toEqual({ name: "general", type: "Private" })
    })

    it("leaves a part out when neither saved nor draft has a name", () => {
        const empty: PreviewModel = { people: [], leave: false }
        const model = buildPreviewModel(empty, { workspace: { name: " " } })
        expect(model.workspace).toBeUndefined()
    })

    it("takes the team step's own list of people in place of the saved one", () => {
        const model = buildPreviewModel(saved, { people: [{ id: "a", name: "Priya" }, { id: "b", name: "Ravi" }] })
        expect(model.people).toEqual([{ id: "a", name: "Priya" }, { id: "b", name: "Ravi" }])
    })

    it("keeps the team step's blank rows, so an added row shows before it's filled", () => {
        const model = buildPreviewModel(saved, { people: [{ id: "a", name: "Ravi" }, { id: "b", name: "" }] })
        expect(model.people).toEqual([{ id: "a", name: "Ravi" }, { id: "b", name: "" }])
    })

    it("keeps the saved people when no step is listing them", () => {
        expect(buildPreviewModel(saved, {}).people).toEqual(saved.people)
    })

    it("shows leave as the HR step's toggle has it", () => {
        expect(buildPreviewModel(saved, { leave: true }).leave).toBe(true)
        expect(buildPreviewModel({ ...saved, leave: true }, { leave: false }).leave).toBe(false)
    })

    it("keeps the saved leave flag when no step is setting it", () => {
        expect(buildPreviewModel({ ...saved, leave: true }, {}).leave).toBe(true)
    })
})

import { describe, expect, it } from "vitest"
import { validateInviteEmail, validateInviteFirstName } from "./inviteValidation"

const row = (email: string, first_name = "Ravi") => ({ email, first_name })
const context = (rows: { email: string; first_name: string }[], invited: { email: string; first_name: string }[] = []) => ({
    rows,
    invited,
    currentUser: "admin@acme.com",
})

describe("validateInviteEmail", () => {
    it("lets an empty row through", () => {
        const empty = row("", "")
        expect(validateInviteEmail(empty, context([empty]))).toBeNull()
    })
    it("wants an email once a first name is typed", () => {
        const named = row("")
        expect(validateInviteEmail(named, context([named]))).toBe("email_required")
    })
    it("rejects a malformed address", () => {
        const bad = row("ravi@")
        expect(validateInviteEmail(bad, context([bad]))).toBe("email_invalid")
    })
    it("rejects the admin's own address, ignoring case and spaces", () => {
        const self = row(" Admin@Acme.com ")
        expect(validateInviteEmail(self, context([self]))).toBe("self")
    })
    it("rejects a second row with the same address", () => {
        const first = row("ravi@acme.com")
        const second = row("RAVI@acme.com")
        expect(validateInviteEmail(first, context([first, second]))).toBe("duplicate")
    })
    it("rejects someone invited earlier in setup", () => {
        const again = row("ravi@acme.com")
        expect(validateInviteEmail(again, context([again], [row("ravi@acme.com")]))).toBe("duplicate")
    })
    it("accepts a new, valid address", () => {
        const fresh = row("ravi@acme.com")
        expect(validateInviteEmail(fresh, context([fresh]))).toBeNull()
    })
})

describe("validateInviteFirstName", () => {
    it("wants a first name once an email is typed", () => {
        expect(validateInviteFirstName(row("ravi@acme.com", " "))).toBe("first_name_required")
    })
    it("lets an empty row through", () => {
        expect(validateInviteFirstName(row("", ""))).toBeNull()
    })
})

import { useRef, useState } from "react"
import { Plus, Camera, Images, FileBox, type LucideIcon, FilesIcon, ChartBar, Video } from "lucide-react"
import { Button } from "@components/ui/button"
import { Drawer, DrawerContent, DrawerDescription, DrawerTitle, DrawerTrigger } from "@components/ui/drawer"
import { useSetAtom } from "jotai"
import { preparingFilesAtom, useAttachFile, type PreparingFile } from "./useFileInput"
import { CreatePollDialog } from "./CreatePollDialog"
import AttachFrappeDocumentDialog from "./AttachFrappeDocumentDialog"
import { isAndroid } from "@utils/platform"
import _ from "@lib/translate"

/** Numbers each native pick, so its rows are cleared together. */
let pickCount = 0

/**
 * Mobile composer overflow: a single "+" opens a bottom sheet of circle icon
 * tiles (camera / photos / files / document / poll — WhatsApp-style). The
 * poll/document dialogs are driven in controlled mode (they live OUTSIDE the
 * sheet, so closing it before opening them is safe); every attach path funnels
 * through the shared useAttachFile, so size/type validation still applies.
 *
 * The tiles are hidden file inputs whose ATTRIBUTES steer the OS picker:
 *   - camera:  `capture` opens the camera directly — but the two platforms
 *     disagree on the accept value. iOS: accept="image/*,video/*" + capture
 *     opens its camera with BOTH photo and video modes — one tile. Android:
 *     `capture` must resolve to a single camera intent (photo OR video), so a
 *     mixed accept makes Chrome silently DROP capture and open the photo
 *     picker instead — hence two tiles there (Camera / Video), each with a
 *     single-type accept. (One capture per trip; capture inputs don't support
 *     multiple.)
 *   - photos:  accept="image/*,video/*", no capture — straight to the library
 *   - files:   unrestricted. iOS insists on its camera/library/file chooser
 *     here — WebKit's accept handling is broken (rdar 36726477) and no accept
 *     value skips the sheet, so restricting types only costs Android's direct
 *     picker its media files. One extra tap on iOS is a platform limitation.
 *   - iOS app: a WKWebView shows that chooser for photos too, anchored to the
 *     closed sheet, so Photos and Files open native pickers (native/pick.ts).
 */
export const MobileComposerActions = ({
    channelID,
}: {
    channelID: string
}) => {
    const [sheetOpen, setSheetOpen] = useState(false)
    const [pollOpen, setPollOpen] = useState(false)
    const [docOpen, setDocOpen] = useState(false)
    const onAddFile = useAttachFile(channelID)
    const setPreparing = useSetAtom(preparingFilesAtom(channelID))
    const cameraInputRef = useRef<HTMLInputElement>(null)
    const videoCaptureRef = useRef<HTMLInputElement>(null)
    const galleryInputRef = useRef<HTMLInputElement>(null)
    const fileInputRef = useRef<HTMLInputElement>(null)

    const iosApp = !!import.meta.env.VITE_NATIVE && window.Capacitor?.getPlatform() === "ios"
    // The ternary keeps the native chunk out of browser builds entirely.
    const pickNative = import.meta.env.VITE_NATIVE
        ? (kind: "files" | "photos") => {
            const pick = ++pickCount
            const others = (rows: PreparingFile[]) => rows.filter((row) => row.pick !== pick)
            const clear = () => setPreparing(others)
            import("../../../native/pick")
                .then((m) => m.pickNativeFiles(kind, {
                    // Shown only once the picker closes with files on their way, never over the open picker.
                    onClosed: () => setPreparing((rows) => [...others(rows), { id: `${pick}`, pick }]),
                    onNamed: (named) => setPreparing((rows) => [
                        ...others(rows),
                        ...named.map((file, index) => ({ id: `${pick}:${index}`, pick, fileName: file.name, size: file.size })),
                    ]),
                }))
                // Cleared in the same step the files are added, so the rows swap without a gap.
                .then((files) => { clear(); if (files.length) onAddFile(files) })
                .catch(() => { })
                .finally(clear)
        }
        : () => { }

    const onPicked = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files?.length) onAddFile(e.target.files)
        e.target.value = ""
    }

    const tiles: { icon: LucideIcon; label: string; onSelect: () => void }[] = [
        { icon: Camera, label: _("Camera"), onSelect: () => cameraInputRef.current?.click() },
        // Android only: capture resolves to ONE camera intent, so photo and
        // video capture need separate tiles (see the file inputs below).
        ...(isAndroid ? [{ icon: Video, label: _("Video"), onSelect: () => videoCaptureRef.current?.click() }] : []),
        { icon: Images, label: _("Photos"), onSelect: () => (iosApp ? pickNative("photos") : galleryInputRef.current?.click()) },
        { icon: FilesIcon, label: _("Files"), onSelect: () => (iosApp ? pickNative("files") : fileInputRef.current?.click()) },
        { icon: ChartBar, label: _("Poll"), onSelect: () => setPollOpen(true) },
        { icon: FileBox, label: _("Document"), onSelect: () => setDocOpen(true) },
    ]

    return (
        <>
            {isAndroid ? (
                <>
                    <input type="file" accept="image/*" capture="environment" ref={cameraInputRef} className="hidden" onChange={onPicked} />
                    <input type="file" accept="video/*" capture="environment" ref={videoCaptureRef} className="hidden" onChange={onPicked} />
                </>
            ) : (
                <input type="file" accept="image/*,video/*" capture="environment" ref={cameraInputRef} className="hidden" onChange={onPicked} />
            )}
            <input type="file" accept="image/*,video/*" multiple ref={galleryInputRef} className="hidden" onChange={onPicked} />
            <input type="file" multiple ref={fileInputRef} className="hidden" onChange={onPicked} />

            <Drawer open={sheetOpen} onOpenChange={setSheetOpen}>
                <DrawerTrigger asChild>
                    <Button type="button" variant="ghost" size="lg" isIconButton aria-label={_("More actions")} className="rounded-full">
                        <Plus className="size-8" />
                    </Button>
                </DrawerTrigger>
                <DrawerContent>
                    <DrawerTitle className="sr-only">{_("Composer actions")}</DrawerTitle>
                    <DrawerDescription className="sr-only">{_("Attach files, polls and more")}</DrawerDescription>
                    {/* Circle icon tiles, WhatsApp-style — every option is an icon */}
                    <div className="grid grid-cols-4 gap-x-2 gap-y-6 px-4 pt-6 pb-10">
                        {tiles.map((tile) => (
                            <button
                                key={tile.label}
                                type="button"
                                className="flex flex-col items-center gap-2"
                                onClick={() => {
                                    setSheetOpen(false)
                                    tile.onSelect()
                                }}
                            >
                                <span className="flex size-14 items-center justify-center rounded-full bg-surface-gray-2 transition-colors active:bg-surface-gray-4 dark:bg-surface-elevation-3 dark:active:bg-surface-gray-4">
                                    <tile.icon className="size-6 text-ink-gray-7" />
                                </span>
                                <span className="text-xs text-ink-gray-6">{tile.label}</span>
                            </button>
                        ))}
                    </div>
                </DrawerContent>
            </Drawer>

            {/* Controlled dialogs opened from the sheet rows (triggers hidden). */}
            <CreatePollDialog channelID={channelID} open={pollOpen} onOpenChange={setPollOpen} hideTrigger />
            <AttachFrappeDocumentDialog channelID={channelID} open={docOpen} onOpenChange={setDocOpen} hideTrigger />
        </>
    )
}

from contextlib import suppress

import frappe
from frappe import _
from frappe.query_builder.functions import Coalesce
from frappe.utils.telemetry import capture

from raven.api.raven_channel_member import add_channel_members
from raven.api.raven_users import give_raven_access, profiles_can_stack
from raven.api.workspaces import add_workspace_members

SETUP_ADMIN_ROLES = ("System Manager", "Raven Admin")
SETUP_STEPS = ("profile", "workspace", "channel", "team", "hr")
# The funnel, named as the Framework wizard names its own, plus a skip since Raven's steps can be skipped.
SETUP_EVENTS = (
	"started_setup",
	"completed_setup_step",
	"skipped_setup_step",
	"went_back_in_setup",
	"left_setup",
)
SETUP_EVENT_PROPERTIES = (
	"mode",
	"step",
	"from_step",
	"to_step",
	"step_number",
	"total_steps",
	"duration_seconds",
)


def is_setup_admin() -> bool:
	"""Only these roles run the first-admin setup flow."""
	return bool(set(SETUP_ADMIN_ROLES) & set(frappe.get_roles()))


def _raven_users_without_workspace() -> list[dict]:
	"""
	Enabled people in Raven who belong to no workspace, except whoever is asking and the
	Administrator account, which install puts in Raven but is nobody's teammate.
	"""
	raven_user = frappe.qb.DocType("Raven User")
	user = frappe.qb.DocType("User")
	member = frappe.qb.DocType("Raven Workspace Member")
	in_a_workspace = frappe.qb.from_(member).select(member.user)
	return (
		frappe.qb.from_(raven_user)
		# The User's photo where the Raven User has none yet; the admin reading this can load it.
		.left_join(user)
		.on(user.name == raven_user.user)
		.select(
			raven_user.user,
			raven_user.full_name,
			Coalesce(raven_user.user_image, user.user_image).as_("user_image"),
		)
		.where(raven_user.type == "User")
		.where(raven_user.enabled == 1)
		.where(raven_user.user.notin(["Administrator", frappe.session.user]))
		.where(raven_user.user.notin(in_a_workspace))
	).run(as_dict=True)


def _system_users_not_in_raven() -> list[dict]:
	"""
	Enabled system users without a working Raven User, except whoever is asking. A Raven User
	that was disabled (the role was taken away) counts as not in Raven: adding them gives it back.
	"""
	in_raven = frappe.get_all("Raven User", filters={"enabled": 1}, pluck="user")
	return frappe.get_all(
		"User",
		filters={
			"user_type": "System User",
			"enabled": 1,
			"name": ["not in", [*in_raven, "Administrator", "Guest", frappe.session.user]],
		},
		fields=["name as user", "full_name", "user_image", "role_profile_name"],
	)


def _site_users() -> list[dict]:
	"""
	Everyone setup could put in the workspace: people in Raven but in no workspace, and system
	users not in Raven yet. Giving someone access saves their User, which a Raven Admin without
	System Manager can't do, so those rows are offered but not addable for them; the same for a
	user whose single role profile can't take Raven's.
	"""
	stack = profiles_can_stack()
	can_edit_users = frappe.has_permission("User", ptype="write")
	users = [{**row, "in_raven": True, "addable": True} for row in _raven_users_without_workspace()]
	for row in _system_users_not_in_raven():
		profile = row.pop("role_profile_name")
		users.append(
			{
				**row,
				"in_raven": False,
				"addable": can_edit_users and (stack or not profile),
				"role_profile": profile or None,
			}
		)
	return sorted(users, key=lambda row: (row["full_name"] or row["user"]).lower())


@frappe.whitelist(methods=["GET"])
def get_site_users() -> list[dict]:
	"""For setup's "already on this site" box."""
	frappe.only_for(SETUP_ADMIN_ROLES)
	return _site_users()


@frappe.whitelist(methods=["GET"])
def get_company() -> dict | None:
	"""
	The site's default company, which ERPNext's setup wizard creates, to start the workspace from.
	Only a public logo is returned: every member sees the workspace logo.
	"""
	frappe.only_for(SETUP_ADMIN_ROLES)
	company = frappe.defaults.get_global_default("company")
	if (
		not company or not frappe.db.table_exists("Company") or not frappe.db.exists("Company", company)
	):
		return None
	logo = frappe.db.get_value("Company", company, "company_logo")
	return {"name": company, "logo": logo if logo and logo.startswith("/files/") else None}


@frappe.whitelist(methods=["POST"])
def add_site_users(users: list[str] | str, workspace: str, channel: str | None = None) -> int:
	"""
	Puts the chosen site users in setup's workspace and channel, giving Raven access to those
	not in Raven yet. Only people on the server's own list count, so this can't add arbitrary
	users; anyone else in the list is dropped.
	"""
	frappe.only_for(SETUP_ADMIN_ROLES)
	frappe.has_permission("Raven Workspace", doc=workspace, ptype="write", throw=True)
	channel_type = None
	if channel:
		channel_workspace, channel_type = frappe.db.get_value(
			"Raven Channel", channel, ["workspace", "type"]
		) or (None, None)
		if channel_workspace != workspace:
			frappe.throw(_("This channel is not in the workspace."))

	offered = {row["user"]: row for row in _site_users() if row["addable"]}
	chosen = [user for user in dict.fromkeys(frappe.parse_json(users) or []) if user in offered]
	if not chosen:
		return 0
	for user in chosen:
		if not offered[user]["in_raven"]:
			give_raven_access(frappe.get_doc("User", user))
	add_workspace_members(workspace, chosen)
	# Everyone in the workspace is in an Open channel; its rows are made on first visit.
	# Otherwise one batch, so the channel gets one "added" message, not one per person.
	if channel and channel_type != "Open":
		add_channel_members(channel, chosen)
	return len(chosen)


@frappe.whitelist(methods=["POST"])
def complete_setup(
	completed_steps: list[str] | str | None = None, skipped_steps: list[str] | str | None = None
):
	"""Ends the setup flow. A second admin finishing later is a no-op."""
	frappe.only_for(SETUP_ADMIN_ROLES)

	finish_frappe_setup()
	frappe.db.set_single_value("Raven Settings", "setup_completed", 1)
	# Boot is cached per user and carries the flag; every admin's copy is now stale.
	frappe.cache.delete_key("bootinfo")

	# Telemetry is best-effort: a malformed step list must not fail the request and undo the flag.
	with suppress(ValueError, TypeError):
		capture(
			"setup_completed",
			"raven",
			properties={
				"completed_steps": _known_steps(completed_steps),
				"skipped_steps": _known_steps(skipped_steps),
			},
		)


def finish_frappe_setup():
	"""
	A Frappe Cloud signup opens Raven before the Framework's setup wizard. Frappe Cloud already
	stored the region and made the first user, so the wizard is finished here with those values.
	Apps with wizard stages of their own, like ERPNext, still need the real wizard.
	"""
	from frappe.desk.page.setup_wizard.setup_wizard import setup_complete
	from frappe.integrations.frappe_providers.frappecloud_billing import is_fc_site

	if frappe.is_setup_complete() or not is_fc_site() or frappe.get_hooks("setup_wizard_stages"):
		return
	result = setup_complete(frappe_setup_args())
	if result.get("status") != "ok":
		# Raven's setup still ends; the Framework wizard stays available in Desk.
		frappe.log_error(
			title="Raven: could not finish the Framework setup wizard", message=result.get("fail")
		)


def frappe_setup_args() -> dict:
	"""What the wizard's first slide would have sent, from the values Frappe Cloud stored."""
	settings = frappe.get_single("System Settings")
	language = frappe.db.get_value("Language", settings.language, "language_name") or "English"
	return {
		"language": language,
		"lang": language,
		"country": settings.country,
		"timezone": settings.time_zone,
		"currency": settings.currency,
		"enable_telemetry": settings.enable_telemetry,
	}


@frappe.whitelist(methods=["POST"])
def record_setup_event(event: str, properties: dict | str | None = None):
	"""
	One event of setup's funnel, from the web app. Only the known events and properties are
	passed on, and nothing here can fail: telemetry is best effort.
	"""
	if event not in SETUP_EVENTS:
		frappe.throw(_("Unknown setup event: {0}").format(event))
	with suppress(Exception):
		capture(event, "raven", properties=_known_properties(properties))


def _known_properties(value) -> dict:
	"""The known properties, with step names and numbers checked."""
	given = frappe.parse_json(value) or {}
	known = {}
	for key in SETUP_EVENT_PROPERTIES:
		if key not in given:
			continue
		if key in ("step", "from_step", "to_step"):
			if given[key] in SETUP_STEPS:
				known[key] = given[key]
		elif key == "mode":
			if given[key] in ("admin", "profile"):
				known[key] = given[key]
		elif given[key] is not None:
			known[key] = frappe.utils.cint(given[key])
	return known


def _known_steps(value) -> list[str]:
	"""Step names from a list or its JSON string; anything unknown is dropped."""
	return [step for step in frappe.parse_json(value) or [] if step in SETUP_STEPS]

import frappe
from frappe import _


def get_enabled_action(action_id: str):
	"""
	Fetch a message action, throwing if it is disabled. The menu only lists
	enabled actions, but a direct API call must not bypass that filter.
	"""
	action = frappe.get_doc("Raven Message Action", action_id)
	if not action.enabled:
		frappe.throw(_("Message Action {0} is disabled").format(action.action_name))
	return action


def filter_values_to_action_fields(action, values: dict) -> dict:
	"""
	Drop any submitted key the action does not define. Without this, the payload
	can override the admin's config — e.g. a `doctype` key would beat
	`action.document_type` in the Create Document merge below.
	"""
	allowed = {field.fieldname for field in action.fields}
	return {key: value for key, value in values.items() if key in allowed}


def resolve_workspace_id(message) -> str | None:
	"""
	The workspace for the `workspace_id` message-field default: the channel's own
	workspace, else the last workspace this user is a member of, else None.
	(v2 used get_last_doc(...).name here — the MEMBER row's name, not a workspace,
	and it raised DoesNotExistError for users with no membership rows.)
	"""
	workspace = frappe.get_cached_value("Raven Channel", message.channel_id, "workspace")
	if workspace:
		return workspace
	return frappe.db.get_value(
		"Raven Workspace Member",
		{"user": frappe.session.user},
		"workspace",
		order_by="modified desc",
	)


@frappe.whitelist(methods=["GET"])
def get_action_defaults(action_id: str, message_id: str):
	"""
	Get the default values for a message action
	"""

	frappe.has_permission(doctype="Raven Message", doc=message_id, ptype="read", throw=True)
	action = get_enabled_action(action_id)
	message = frappe.get_doc("Raven Message", message_id)

	# The canonical /message resolver route redirects to the right place for every
	# message (channel, DM, or thread reply) — same shape the web app's own
	# "Copy message link" uses. No workspace/thread special-casing needed.
	message_url = frappe.utils.get_url(f"/raven/message/{message.name}")

	# Loop through the fields in the action and get the default values from the message
	defaults = {}

	for field in action.fields:
		if not field.default_value:
			continue

		if field.default_value_type == "Static":
			defaults[field.fieldname] = field.default_value

		if field.default_value_type == "Message Field":
			if field.default_value == "message_url":
				val = message_url
			elif field.default_value == "workspace_id":
				val = resolve_workspace_id(message)
			else:
				val = message.get(field.default_value)
			if val:
				defaults[field.fieldname] = val

		if field.default_value_type == "Jinja":

			# Message actions are set by Raven Admins only. The renderer is sandboxed.
			# nosemgrep: frappe-ssti
			val = frappe.render_template(
				field.default_value, {"message": {"message_url": message_url, **message.as_dict()}}
			)

			if val:
				defaults[field.fieldname] = val

	return defaults


@frappe.whitelist(methods=["POST"])
def execute_action(action_id: str, message_id: str, values: dict):
	"""
	Execute a message action
	"""

	frappe.has_permission(doctype="Raven Message", doc=message_id, ptype="read", throw=True)
	action = get_enabled_action(action_id)
	message = frappe.get_doc("Raven Message", message_id)
	values = filter_values_to_action_fields(action, values)

	if action.action == "Create Document":
		doc = frappe.get_doc({"doctype": action.document_type, **values})
		doc.insert()

		# Link message to the document if no link exists already
		if not message.link_doctype and not message.link_document:
			message.flags.editing_metadata = True
			message.link_doctype = doc.doctype
			message.link_document = doc.name
			# Ignore permissions to allow editing of the document
			message.save(ignore_permissions=True)

		# Resolve the document's URL server-side (hook-overridable for apps that
		# don't live under /app, e.g. Frappe CRM). Relative, so the client opens
		# it on whatever origin the user is on.
		from raven.api.document_link import get as get_document_link

		link = get_document_link(doc.doctype, doc.name, with_site_url=False)

		return {
			"message": "Document created successfully",
			"document": doc.name,
			"doctype": doc.doctype,
			"link": link,
		}

	if action.action == "Custom Function":
		# Call the function with the values
		function_name = frappe.get_attr(action.custom_function_path)

		if function_name:
			return function_name(**values)
		else:
			frappe.throw(_("Function {0} not found").format(action.custom_function_path))

	if action.action == "Server Script":
		script = frappe.get_doc("Server Script", action.server_script)
		if script.disabled:
			frappe.throw(_("Server Script {0} is disabled").format(action.server_script))
		script.execute_method()

import type { RavenChannel } from "@raven/types/RavenChannelManagement/RavenChannel"

/** Someone in the DM list; a blank name is an invite row not filled in yet. The id keeps their row mounted as the list changes. */
export type PreviewPerson = { id: string; name: string; image?: string }

/** What the preview window shows; absent parts render as skeleton bars. */
export type PreviewModel = {
    profile?: { name: string; image?: string }
    workspace?: { name: string; logo?: string }
    channel?: { name: string; type?: RavenChannel["type"] }
    people: PreviewPerson[]
    /** Frappe HR's leave indicator is on: people show on leave. */
    leave: boolean
}

/** The open step's unsaved fields. Cleared whenever the step changes. The team step lists everyone, so its people replace the saved ones. */
export type PreviewDraft = Partial<Pick<PreviewModel, "profile" | "workspace" | "channel" | "people" | "leave">>

const filled = (value?: string): value is string => !!value?.trim()

/** A named part from the draft over the saved one; a blank name falls back to the saved one. */
const merge = <P extends { name: string }>(saved?: P, draft?: Partial<P>): P | undefined => {
    const name = filled(draft?.name) ? draft.name.trim() : saved?.name
    if (!filled(name)) return undefined
    return { ...saved, ...draft, name } as P
}

export const buildPreviewModel = (saved: PreviewModel, draft: PreviewDraft): PreviewModel => ({
    profile: merge(saved.profile, draft.profile),
    workspace: merge(saved.workspace, draft.workspace),
    channel: merge(saved.channel, draft.channel),
    people: draft.people ?? saved.people,
    leave: draft.leave ?? saved.leave,
})

import { describe, expect, it } from "vitest"
import { mergeSuggestions, sameEmojiSet, toSuggestedSet, type ReactionUsageRow } from "./reactionUsage"
import type { QuickEmoji } from "./preferences"

const row = (reaction: string, uses: number, custom = false, name?: string): ReactionUsageRow => ({
    reaction,
    is_custom: custom ? 1 : 0,
    reaction_escaped: name,
    uses,
})

describe("toSuggestedSet", () => {
    it("maps native and custom rows, keeping server order", () => {
        const set = toSuggestedSet([row("👍", 5), row("/files/party.png", 3, true, "party-blob")], 2)
        expect(set).toEqual([
            { id: "👍", native: "👍" },
            { id: "party-blob", src: "/files/party.png" },
        ])
    })

    it("returns nothing unless a FULL set exists (applied as one unit)", () => {
        expect(toSuggestedSet([row("👍", 5)], 2)).toEqual([])
        expect(toSuggestedSet(undefined, 2)).toEqual([])
    })

    it("caps at n", () => {
        expect(toSuggestedSet([row("a", 3), row("b", 2), row("c", 1)], 2)).toHaveLength(2)
    })
})

describe("sameEmojiSet", () => {
    const set = (...ids: string[]): QuickEmoji[] => ids.map((id) => ({ id }))

    it("matches regardless of order", () => {
        expect(sameEmojiSet(set("a", "b"), set("b", "a"))).toBe(true)
    })

    it("matches a picker slug id against a char id via native", () => {
        expect(sameEmojiSet([{ id: "❤️", native: "❤️" }], [{ id: "heart", native: "❤️" }])).toBe(true)
    })

    it("differs on any member or length", () => {
        expect(sameEmojiSet(set("a", "b"), set("a", "c"))).toBe(false)
        expect(sameEmojiSet(set("a"), set("a", "b"))).toBe(false)
    })

    it("compares as a multiset — duplicates must match too", () => {
        expect(sameEmojiSet(set("a", "a", "b"), set("a", "b", "b"))).toBe(false)
        expect(sameEmojiSet(set("a", "a", "b"), set("b", "a", "a"))).toBe(true)
    })
})

describe("mergeSuggestions", () => {
    const set = (...ids: string[]): QuickEmoji[] => ids.map((id) => ({ id }))
    const ids = (emojis: QuickEmoji[]) => emojis.map((emoji) => emoji.id)

    it("replaces the first n slots and keeps the rest", () => {
        const next = mergeSuggestions(set("a", "b", "c", "d", "e", "f"), set("w", "x", "y", "z"), 4)
        expect(ids(next)).toEqual(["w", "x", "y", "z", "e", "f"])
    })

    it("replaces everything when n covers all slots", () => {
        const next = mergeSuggestions(set("a", "b", "c"), set("x", "y", "z"), 3)
        expect(ids(next)).toEqual(["x", "y", "z"])
    })

    it("refills a kept slot that would duplicate a suggestion", () => {
        // "e" is now suggested; its old slot 5 gets a replaced head emoji.
        const next = mergeSuggestions(set("a", "b", "c", "d", "e", "f"), set("e", "x", "y", "z"), 4)
        expect(ids(next)).toEqual(["e", "x", "y", "z", "a", "f"])
    })

    it("drops a duplicate kept slot when no refill is free", () => {
        // Every old head emoji is suggested, so nothing can refill slot 5.
        const next = mergeSuggestions(set("a", "b", "a", "x"), set("a", "b", "x"), 3)
        expect(ids(next)).toEqual(["a", "b", "x"])
    })
})

import { afterEach, describe, expect, it, vi } from "vitest"
